        new("python-project-foundations", "Project studio", 13, "Start a production-shaped project", "A clean project boundary makes every later decision cheaper.", "Separate application code, tests, configuration, and delivery concerns from the first commit.", "Create a small learning-service API and evolve it throughout the track. Keep source in a package, tests outside it, configuration in the environment, and dependencies declared in project metadata. A professional project is reproducible before it is clever.", "learning_service/\n  src/learning_service/\n  tests/\n  pyproject.toml", new(ExerciseKind.MultipleChoice, "Choose the boundary", "Which concern should not be hard-coded into application source?", ["Choose one answer"], null, "config", [new("config", "Deployment-specific configuration and secrets"), new("domain", "A domain rule expressed in code"), new("test", "A test case that documents behavior")], "Environment-specific values belong outside the source tree.", ["Separates configuration"]), "python-environments-packaging", PythonDocs),
        new("python-environments-packaging", "Project studio", 14, "Use environments and packages responsibly", "Reproducible dependencies are a delivery requirement.", "A virtual environment isolates a project’s installed packages from other projects and the system interpreter.", "Pin or constrain direct dependencies according to your team’s policy, review upgrades, and use a lock file when your toolchain supports one. Keep the supported Python range explicit in `pyproject.toml`; test it in CI. Do not install application dependencies globally.", "[project]\nname = \"learning-service\"\nrequires-python = \">=3.14\"\ndependencies = [\"fastapi\", \"uvicorn\"]", new(ExerciseKind.MultipleChoice, "Choose the safe setup", "Why create a virtual environment for a project?", ["Choose one answer"], null, "isolate", [new("isolate", "It isolates that project’s installed dependencies"), new("speed", "It makes Python syntax execute faster"), new("secret", "It encrypts environment variables")], "Think about dependency isolation, not security or performance.", ["Uses isolated dependencies"]), "python-control-flow-collections", PythonDocs),
        new("python-control-flow-collections", "Core Python", 15, "Control flow and collections", "Choose the collection that states the operation you need.", "Lists preserve order, dictionaries map keys to values, sets model uniqueness, and tuples model fixed positional values.", "Use `for` to iterate, `enumerate` when an index is truly meaningful, and comprehensions when they make a transformation clearer—not denser. Avoid modifying a collection while iterating over it. Prefer a direct loop when a comprehension gains multiple conditions or side effects.", "active_names = [user.name for user in users if user.active]\nby_id = {user.id: user for user in users}", new(ExerciseKind.MultipleChoice, "Pick the collection", "Which type best represents unique permission names?", ["Choose one answer"], null, "set", [new("set", "A set"), new("list", "A list because it always prevents duplicates"), new("tuple", "A tuple because it is mutable")], "Uniqueness is the key requirement here.", ["Selects a collection by semantics"]), "python-modules-imports", PythonDocs),
        new("python-modules-imports", "Core Python", 16, "Modules, imports, and package boundaries", "Imports form an architectural dependency graph.", "A module is a namespace; a package groups related modules into a distributable unit.", "Keep imports explicit and acyclic. Put stable domain concepts near the center of the dependency graph; adapters such as HTTP, database, and framework code should depend inward, not the reverse. Avoid executable work at import time because imports also run in tests and tooling.", "# application/services/enroll.py\nfrom application.domain.lesson import Lesson\n\ndef enroll(lesson: Lesson) -> None:\n    ...", new(ExerciseKind.MultipleChoice, "Protect the graph", "What is the best reason to avoid side effects at import time?", ["Choose one answer"], null, "predictable", [new("predictable", "Imports remain predictable for tests, tools, and callers"), new("faster", "It makes every import asynchronous"), new("private", "It hides modules from other packages")], "Importing should primarily define names, not start application work.", ["Designs predictable imports"]), "python-objects-protocols", PythonDocs),
        new("python-objects-protocols", "Core Python", 17, "Objects, protocols, and composition", "Model behavior through small interfaces and composition.", "Protocols describe the operations a collaborator must support without forcing inheritance.", "Use classes where state and behavior belong together, dataclasses for simple value objects, and `Protocol` for structural contracts at seams. Prefer composition over inheritance: inject a clock, repository, or sender rather than deriving from a deep base class.", "from typing import Protocol\n\nclass LessonRepository(Protocol):\n    def get(self, lesson_id: str) -> Lesson | None: ...", new(ExerciseKind.MultipleChoice, "Choose the seam", "What does a Protocol help you express?", ["Choose one answer"], null, "behavior", [new("behavior", "The behavior a collaborator must provide"), new("database", "A database schema migration"), new("runtime", "A mandatory runtime inheritance tree")], "Protocols support structural, behavior-oriented boundaries.", ["Uses composition seams"]), "python-errors-resources", PythonDocs),
        new("python-errors-resources", "Core Python", 18, "Exceptions and resource safety", "Handle errors where you can add context or recover.", "`with` guarantees cleanup for context-managed resources, even when an exception is raised.", "Catch specific exceptions at boundaries. Preserve the original exception as the cause when translating it. Use `finally` or a context manager for cleanup; do not catch `Exception` merely to log and continue. For an API, map known domain failures to intentional client responses and let unexpected failures reach centralized handling.", "try:\n    with open(path, encoding=\"utf-8\") as file:\n        return file.read()\nexcept OSError as error:\n    raise ConfigurationError(path) from error", new(ExerciseKind.MultipleChoice, "Keep the cause", "What does `raise NewError(...) from error` preserve?", ["Choose one answer"], null, "chain", [new("chain", "The causal exception chain for debugging"), new("retry", "An automatic network retry"), new("type", "Runtime type enforcement")], "The original cause remains visible in the traceback.", ["Preserves failure context"]), "python-testing-pytest", PytestDocs),
        new("python-testing-pytest", "Quality engineering", 19, "Test with pytest and a deliberate pyramid", "Tests should make change safer and feedback faster.", "Unit tests protect local rules; integration tests prove behavior at real boundaries; a few end-to-end tests protect the critical journey.", "Name tests after behavior, arrange only the required state, and assert the observable result. Use fixtures for explicit setup, factories for readable domain data, and fakes at your own ports. Mock third-party boundaries sparingly; tests coupled to call order make refactoring expensive.", "def test_enroll_rejects_an_archived_lesson() -> None:\n    result = enroll(archived_lesson)\n    assert result.is_error", new(ExerciseKind.MultipleChoice, "Choose the assertion", "What should an HTTP integration test primarily assert?", ["Choose one answer"], null, "contract", [new("contract", "The observable status and response contract"), new("private", "The internal helper call order"), new("time", "An exact timestamp in every response")], "Test what an API client can rely on.", ["Tests observable contracts"]), "python-http-clients", PytestDocs),
        new("python-http-clients", "Web foundations", 20, "Call HTTP services resiliently", "Every network call needs a bounded failure policy.", "Timeouts, retries, idempotency, and error classification are part of a client contract.", "Set connect and read timeouts deliberately. Retry only transient failures and only when the operation is safe or protected by an idempotency key. Bound retry attempts with backoff and jitter; report dependency failures with enough context to diagnose them without leaking sensitive data.", "async with httpx.AsyncClient(timeout=5.0) as client:\n    response = await client.get(url)\n    response.raise_for_status()", new(ExerciseKind.MultipleChoice, "Retry safely", "When is an automatic retry most defensible?", ["Choose one answer"], null, "idempotent", [new("idempotent", "A transient failure on an idempotent request with a bounded policy"), new("invalid", "A validation error from the caller"), new("payment", "A payment POST without idempotency protection")], "Retries can duplicate effects when operations are not idempotent.", ["Designs bounded retries"]), "python-api-contracts", FastApiDocs),
        new("python-api-contracts", "API delivery", 21, "Design API contracts before handlers", "A stable contract lets clients and teams evolve independently.", "A resource shape, status code, error format, pagination contract, and idempotency policy are all API design.", "Write examples for success and failure before implementation. Validate at the boundary, use consistent error envelopes, return `201 Created` with a location or representation when creating a resource, and define cursor semantics before large collections need them. Version only when you cannot evolve compatibly.", "POST /v1/enrollments\nIdempotency-Key: 7fd...\n\n201 Created\nLocation: /v1/enrollments/42", new(ExerciseKind.MultipleChoice, "Choose compatibility", "What is the least disruptive way to evolve a response?", ["Choose one answer"], null, "additive", [new("additive", "Add an optional field with documented semantics"), new("rename", "Rename a required field without a migration"), new("status", "Change successful requests from 200 to 500")], "Additive changes preserve existing clients more often.", ["Designs compatible contracts"]), "python-fastapi-architecture", FastApiDocs),
        new("python-fastapi-architecture", "API delivery", 22, "Structure a FastAPI application", "Framework code should compose the application; it should not become the application.", "FastAPI dependency injection is useful at the delivery boundary, while services and domain rules remain ordinary Python.", "Group routers by capability, keep Pydantic request and response models at the API edge, and inject repositories or services through explicit providers. Use lifespan handling for shared clients and connections. Generate OpenAPI from a truthful contract; do not expose internal implementation shapes by accident.", "router = APIRouter(prefix=\"/lessons\")\n\n@router.get(\"/{lesson_id}\", response_model=LessonResponse)\ndef get_lesson(lesson_id: str, service: LessonServiceDep) -> LessonResponse:\n    return service.get(lesson_id)", new(ExerciseKind.MultipleChoice, "Place the rule", "Where should a business rule about enrollment eligibility live?", ["Choose one answer"], null, "service", [new("service", "In a domain or application service, independent of the route"), new("router", "Only in an HTTP router"), new("schema", "Only in the OpenAPI document")], "The rule should remain usable outside HTTP delivery.", ["Separates delivery from business rules"]), "python-async-correctness", FastApiDocs),
        new("python-async-correctness", "API delivery", 23, "Async without accidental blocking", "Async improves waiting efficiency only when the whole call path cooperates.", "An `async def` endpoint should await non-blocking I/O; CPU-bound or blocking work needs a different execution strategy.", "Use async-compatible libraries for network and database I/O. Do not call blocking file, database, or CPU-heavy operations directly in the event loop. Bound concurrent fan-out, propagate cancellation, and measure queueing and latency before adding concurrency.", "async def lesson(lesson_id: str, client: httpx.AsyncClient) -> Lesson:\n    response = await client.get(f\"/lessons/{lesson_id}\")\n    return Lesson.model_validate(response.json())", new(ExerciseKind.MultipleChoice, "Protect the event loop", "What should happen to CPU-bound report generation?", ["Choose one answer"], null, "worker", [new("worker", "Run it in a worker process or purpose-built compute system"), new("await", "Add `await` to make CPU work non-blocking"), new("route", "Keep it in the request path with no timeout")], "Awaiting does not make CPU work asynchronous.", ["Avoids event-loop blocking"]), "python-database-sqlalchemy", DjangoDocs),
