        new("python-flask-production", "Framework practice", 26, "Build Flask with explicit composition", "Flask stays maintainable when the application owns its wiring.", "Application factories, blueprints, and extension initialization make Flask configuration testable.", "Create the app from configuration, register blueprints and error handlers in one composition root, and initialize extensions with `init_app`. Keep request handlers thin. Use a production WSGI server and set proxy, session, and configuration behavior intentionally; the built-in development server is not the production deployment model.", "def create_app(config: Config) -> Flask:\n    app = Flask(__name__)\n    app.config.from_mapping(config.as_dict())\n    db.init_app(app)\n    app.register_blueprint(lessons_bp)\n    return app", new(ExerciseKind.MultipleChoice, "Choose the composition root", "Where should Flask extensions be connected to a specific app?", ["Choose one answer"], null, "init", [new("init", "During application creation with explicit configuration"), new("import", "As irreversible side effects during every import"), new("view", "Inside each individual view function")], "Application creation makes wiring visible and testable.", ["Composes a Flask application"]), "python-django-production", DjangoDocs),
