    public static readonly Lesson[] PythonAllLessons = PythonLessons.Concat(PythonProfessionalLessons).ToArray();
    public static readonly Dictionary<string, Lesson> BySlug = Lessons.Concat(PythonAllLessons).ToDictionary(lesson => lesson.Slug, StringComparer.Ordinal);
    public static readonly Course Course = BuildCourse("csharp-dotnet", "C# / .NET: zero to staff", "csharp", "C# 14", ".NET 10", "2026-08-12", Lessons);
    public static readonly Course PythonCourse = BuildCourse("python-web", "Python Web: zero to staff", "python", "Python 3.14", "FastAPI · Flask · Django", "2026-08-13", PythonAllLessons);
    public static readonly IReadOnlyDictionary<string, Course> Courses = new Dictionary<string, Course>(StringComparer.Ordinal)
    {
        [Course.Id] = Course,
        [PythonCourse.Id] = PythonCourse
    };
    public static readonly IReadOnlyList<CourseCatalogItem> Catalog =
    [
        new(Course.Id, Course.Title, Course.LanguageId, Course.LanguageVersion, Course.FrameworkVersion, true),
        new(PythonCourse.Id, PythonCourse.Title, PythonCourse.LanguageId, PythonCourse.LanguageVersion, PythonCourse.FrameworkVersion, true)
    ];

    private static Course BuildCourse(string id, string title, string languageId, string languageVersion, string frameworkVersion, string reviewed, Lesson[] lessons) => new(id, title, languageId, languageVersion, frameworkVersion, reviewed,
        lessons.GroupBy(lesson => lesson.Module).OrderBy(group => group.Min(lesson => lesson.Order)).Select(group => new Module(group.Key.ToLowerInvariant().Replace(' ', '-'), group.Key, group.Key.Contains("foundations", StringComparison.OrdinalIgnoreCase) ? "Beginner" : group.Key.Contains("staff", StringComparison.OrdinalIgnoreCase) ? "Staff" : "Professional", group.OrderBy(lesson => lesson.Order).Select(l => new LessonSummary(l.Slug, l.Title, l.Order)).ToArray())).ToArray());
}
